from typing import List, Tuple

def count_squares(lines: List[str]) -> int:
    def is_square(corners: List[Tuple[int, int]], side_length: int) -> bool:
        return all((x, y) in corners for x in range(corners[0][0], corners[0][0] + side_length) for y in range(corners[0][1], corners[0][1] + side_length))

    def find_corners(line: str) -> List[Tuple[int, int]]:
        return [(i, j) for i, char in enumerate(line) if char == '+']

    def find_squares(line: str, side_length: int) -> List[List[Tuple[int, int]]]:
        corners = find_corners(line)
        return [[(corners[i], corners[j], corners[i + side_length], corners[j + side_length]) for j in range(len(corners) - side_length + 1)] for i in range(len(corners) - side_length + 1)]

    def count_squares_in_line(line: str) -> int:
        side_length = 2
        count = 0
        while side_length <= len(line):
            squares = find_squares(line, side_length)
            count += sum(1 for square in squares if is_square(square, side_length))
            side_length += 1
        return count

    return sum(count_squares_in_line(line) for line in lines)
